package com.crm.customer;
import com.crm.customer.service.*;import com.crm.customer.dto.*;import jakarta.validation.Validation;import org.junit.jupiter.api.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.junit.jupiter.api.Assertions.*;
class CustomerXlsxImportTest {ICustomerService customers=mock(ICustomerService.class);jakarta.validation.ValidatorFactory validator=Validation.buildDefaultValidatorFactory();CustomerCsvService csv=new CustomerCsvService(customers,validator.getValidator());CustomerXlsxService xlsx=new CustomerXlsxService(csv);@AfterEach void close(){validator.close();}
 static byte[] archive(Map<String,String> parts)throws Exception{var bytes=new ByteArrayOutputStream();try(var zip=new ZipOutputStream(bytes)){for(var part:parts.entrySet()){zip.putNextEntry(new ZipEntry(part.getKey()));zip.write(part.getValue().getBytes(StandardCharsets.UTF_8));zip.closeEntry();}}return bytes.toByteArray();}
 static Map<String,String> parts(String sheet){var parts=new LinkedHashMap<String,String>();parts.put("[Content_Types].xml","<Types/>");parts.put("xl/workbook.xml","<workbook><sheets><sheet name=\"Contacts\"/></sheets></workbook>");parts.put("xl/worksheets/sheet1.xml",sheet);return parts;}
 static String cell(String address,String text){return "<c r=\""+address+"\" t=\"inlineStr\"><is><t>"+text+"</t></is></c>";}
 static String sheet(String name){return "<worksheet><sheetData><row r=\"1\">"+cell("A1",name)+cell("B1","email")+"</row><row r=\"2\">"+cell("A2","Acme")+cell("B2","sales@example.invalid")+"</row></sheetData></worksheet>";}
 @Test void importsInlineStringsUsingCsvValidationAndNeverUpdatesExistingRows()throws Exception{when(customers.createCustomer(any())).thenReturn(new CustomerResponse());var r=xlsx.read(archive(parts(sheet("name"))),customers::createCustomer);assertEquals(1,r.acceptedRows());assertEquals(0,r.rejectedRows());verify(customers).createCustomer(argThat(c->c.getName().equals("Acme")&&c.getEmail().equals("sales@example.invalid")));verify(customers,never()).updateCustomer(any(),any());}
 @Test void sharedStringsNumericReferencesAndEmptyCellsAreSupported()throws Exception{var p=parts("<worksheet><sheetData><row r=\"1\"><c r=\"A1\" t=\"s\"><v>0</v></c>"+cell("B1","assignedEmployeeId")+"</row><row r=\"2\"><c r=\"A2\" t=\"s\"><v>1</v></c><c r=\"B2\"><v>101</v></c></row></sheetData></worksheet>");p.put("xl/sharedStrings.xml","<sst><si><t>name</t></si><si><t>Acme</t></si></sst>");var r=xlsx.read(archive(p),c->{assertEquals(101L,c.getAssignedEmployeeId());return new CustomerResponse();});assertEquals(1,r.acceptedRows());}
 @Test void rejectsFormulasBeforeAnyCreationEvenAfterValidRows()throws Exception{String data=sheet("name").replace("</sheetData>","<row r=\"3\"><c r=\"A3\"><f>1+1</f><v>2</v></c></row></sheetData>");assertThrows(IllegalArgumentException.class,()->xlsx.read(archive(parts(data)),customers::createCustomer));verifyNoInteractions(customers);}
 @Test void rejectsMacrosExternalRelationshipsAndMultipleSheets()throws Exception{var macro=parts(sheet("name"));macro.put("xl/vbaProject.bin","synthetic");assertThrows(IllegalArgumentException.class,()->xlsx.toCsv(archive(macro)));var links=parts(sheet("name"));links.put("xl/_rels/workbook.xml.rels","<Relationships><Relationship TargetMode=\"External\" Target=\"https://example.invalid\"/></Relationships>");assertThrows(IllegalArgumentException.class,()->xlsx.toCsv(archive(links)));var many=parts(sheet("name"));many.put("xl/worksheets/sheet2.xml",sheet("name"));assertThrows(IllegalArgumentException.class,()->xlsx.toCsv(archive(many)));}
 @Test void rejectsDtdAndInvalidZipWithoutExternalRead()throws Exception{var p=parts("<!DOCTYPE x [<!ENTITY x SYSTEM \"file:///does-not-exist\">]><worksheet><sheetData/></worksheet>");assertThrows(IllegalArgumentException.class,()->xlsx.toCsv(archive(p)));assertThrows(IllegalArgumentException.class,()->xlsx.toCsv(new byte[]{1,2,3}));}
 @Test void rejectsUnknownDuplicateAndMissingRequiredColumns()throws Exception{for(String header:List.of("unexpected","email",""))assertThrows(IllegalArgumentException.class,()->xlsx.read(archive(parts(sheet(header))),customers::createCustomer));String duplicate=sheet("name").replace(">email<",">name<");assertThrows(IllegalArgumentException.class,()->xlsx.read(archive(parts(duplicate)),customers::createCustomer));verifyNoInteractions(customers);}
 @Test void reportsDuplicatesInvalidRowsAndUnverifiedEmployeesIndividually()throws Exception{String sheet="<worksheet><sheetData><row r=\"1\">"+cell("A1","name")+cell("B1","assignedEmployeeId")+"</row><row r=\"2\">"+cell("A2","Existing")+"</row><row r=\"3\">"+cell("A3","New")+cell("B3","101")+"</row><row r=\"4\">"+cell("A4","Accepted")+"</row><row r=\"5\">"+cell("A5","Invalid")+cell("B5","-1")+"</row></sheetData></worksheet>";var r=xlsx.read(archive(parts(sheet)),c->{if(c.getName().equals("Existing"))throw new IllegalArgumentException("Duplicate name");if(c.getAssignedEmployeeId()!=null)throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_GATEWAY,"private");return new CustomerResponse();});assertEquals(4,r.totalRows());assertEquals(1,r.acceptedRows());assertEquals(3,r.rejectedRows());assertFalse(r.issues().toString().contains("private"));assertEquals(List.of(2,3,5),r.issues().stream().map(CustomerCsvService.ImportIssue::row).toList());}
 @Test void fileRowsColumnsTextAndExpandedZipAreBounded()throws Exception{assertThrows(IllegalArgumentException.class,()->xlsx.toCsv(new byte[5*1024*1024+1]));assertThrows(IllegalArgumentException.class,()->xlsx.toCsv(archive(parts(sheet("name").replace("r=\"2\"","r=\"2002\"")))));assertThrows(IllegalArgumentException.class,()->xlsx.toCsv(archive(parts(sheet("name").replace("A2","J2")))));assertThrows(IllegalArgumentException.class,()->xlsx.toCsv(archive(parts(sheet("name").replace("Acme","x".repeat(5001))))));var p=parts(sheet("name"));p.put("xl/unused.xml","x".repeat(10*1024*1024));assertThrows(IllegalArgumentException.class,()->xlsx.toCsv(archive(p)));}
 @Test void exportedValuesOnlyWorkbookCanBeReadWithoutExecutingText()throws Exception{var row=new CustomerResponse();row.setName("=SUM(1,2)");when(customers.getAllCustomersPaged(anyInt(),anyInt(),any(),any(),any(),any(),any(),any(),any())).thenReturn(new org.springframework.data.domain.PageImpl<>(List.of(row)));byte[] bytes=csv.exportXlsx(null,null,null,null,null);String text=new String(xlsx.toCsv(bytes),StandardCharsets.UTF_8);assertTrue(text.contains("SUM(1,2)"));assertTrue(text.contains("name"));}
}
